def build_all():
    b=Book("java","Java17+ senza feature preview",["https://dev.java/learn/", "https://docs.oracle.com/en/java/javase/17/docs/api/"],"JDK17+ nel PATH, comandi javac e java. Non basta un JRE; nessuna dipendenza Maven/Gradle necessaria.")
    def add(title,desc,body,expected,tags,definitions=""):
        source=IMPORTS+'\npublic class Main{\npublic static void main(String[] args)throws Exception{\n'+body+'\n}\n'+definitions+'\n}\n'
        program(b,title,desc,source,filename="Main.java",command="javac -encoding UTF-8 --release 17 Main.java\njava Main",expected=expected,tags=tags.split(),error="Il nome della classe pubblica deve corrispondere a Main.java. Usare JDK17+ e non abilitare feature preview per questi esempi.")
    add("Convertire un intero gestendo il testo invalido", "Distingue input accettato e NumberFormatException invece di usare zero come sentinella.",'''for(String text:new String[]{"42","abc"}){try{System.out.println(Integer.parseInt(text));}catch(NumberFormatException error){System.out.println("intero non valido");}}''',"42 e intero non valido.","integer parse validation")
    add("Calcolare importi esatti con BigDecimal", "Costruisce il decimale da stringa e sceglie esplicitamente l'arrotondamento.",'''BigDecimal value=new BigDecimal("1.005").setScale(2,RoundingMode.HALF_UP);System.out.println(value.toPlainString());''',"1.01; non costruire l'importo da un double approssimato.","bigdecimal rounding money")
    add("Normalizzare testo Unicode Java", "Confronta forme composte e scomposte dopo normalizzazione NFC.",'''String a="café",b="cafe\\u0301";System.out.println(a.equals(b));System.out.println(Normalizer.normalize(a,Normalizer.Form.NFC).equals(Normalizer.normalize(b,Normalizer.Form.NFC)));''',"false true", "unicode normalizer nfc")
    add("Comporre testo con StringBuilder", "Evita concatenazioni ripetute dentro un ciclo che costruisce un report.",'''StringBuilder builder=new StringBuilder();for(int i=1;i<=3;i++){builder.append("Riga ").append(i).append(System.lineSeparator());}System.out.print(builder);''',"Tre righe numerate.","stringbuilder formatting text")
    add("Estrarre gruppi da una regex", "Controlla matches prima di usare un gruppo e valida l'intera stringa.",'''Matcher matcher=Pattern.compile("item-(\\\\d+)").matcher("item-123");if(matcher.matches())System.out.println(matcher.group(1));''',"123", "regex pattern matcher group")
    add("Analizzare una data civile con LocalDate", "Legge un formato esplicito e somma giorni senza fusi orari.",'''LocalDate date=LocalDate.parse("29/10/2026",DateTimeFormatter.ofPattern("dd/MM/uuuu"));System.out.println(date.plusDays(7));''',"2026-11-05", "localdate formatter date")
    add("Convertire istanti con ZoneId", "Applica le regole del fuso Europe/Rome a un istante UTC.",'''Instant instant=Instant.parse("2026-01-10T12:00:00Z");System.out.println(instant.atZone(ZoneId.of("Europe/Rome")));''',"2026-01-10T13:00+01:00[Europe/Rome]; usa il database fusi del JDK.","zoneid instant timezone")
    add("Calcolare una durata temporale", "Usa Duration per un intervallo fra istanti, senza confonderlo con mesi civili.",'''Duration duration=Duration.between(Instant.parse("2026-10-29T10:00:00Z"),Instant.parse("2026-10-29T11:30:00Z"));System.out.println(duration.toMinutes());''',"90", "duration instant time")
    add("Copiare una lista senza condividere il contenitore", "Costruisce un ArrayList distinto; gli elementi oggetto resterebbero condivisi.",'''List<String> source=new ArrayList<>(List.of("a","b"));List<String> copy=new ArrayList<>(source);copy.add("c");System.out.println(source.size()+" "+copy.size());''',"2 3", "arraylist copy mutable")
    add("Filtrare una sequenza con Stream", "Produce una lista di valori selezionati senza modificare la sorgente.",'''List<Integer> result=List.of(1,2,3,4).stream().filter(value->value%2==0).toList();System.out.println(result);''',"[2, 4]; Stream.toList produce una lista non modificabile.","stream filter list")
    add("Trasformare valori con map", "Deriva i quadrati leggendo una sequenza di interi.",'''System.out.println(List.of(2,3,4).stream().map(value->value*value).toList());''',"[4, 9, 16]", "stream map projection")
    add("Ridurre una sequenza con identità", "Definisce un accumulatore iniziale valido anche per una sequenza vuota.",'''int total=List.of(2,3,5).stream().reduce(0,Integer::sum);System.out.println(total);''',"10", "stream reduce sum")
    add("Raggruppare e contare con Collectors", "Calcola frequenze per parola con groupingBy e counting.",'''Map<String,Long> counts=List.of("rosso","blu","rosso").stream().collect(Collectors.groupingBy(value->value,Collectors.counting()));System.out.println(counts.get("rosso"));''',"2", "collectors groupingby counting")
    add("Ordinare record con Comparator", "Combina ordinamento per cognome e nome con thenComparing.",'''List<Person> rows=new ArrayList<>(List.of(new Person("Rossi","Luca"),new Person("Rossi","Ada")));rows.sort(Comparator.comparing(Person::surname).thenComparing(Person::name));System.out.println(rows.get(0).name());''',"Ada", "comparator thencomparing record", "record Person(String surname,String name){}")
    add("Gestire una ricerca assente con Optional", "Distingue l'assenza senza restituire null dal metodo di ricerca.",'''Optional<String> found=List.of("Ada","Luca").stream().filter(name->name.startsWith("Z")).findFirst();System.out.println(found.orElse("assente"));''',"assente; non usare Optional.get senza prima verificare presenza.","optional findfirst default")
    add("Deduplicare mantenendo l'ordine con LinkedHashSet", "Sceglie un insieme che conserva l'ordine di inserimento.",'''Set<Integer> unique=new LinkedHashSet<>(List.of(3,1,3,2,1));System.out.println(unique);''',"[3, 1, 2]", "linkedhashset unique order")
    add("Accumulare conteggi con Map.merge", "Aggiorna una chiave esistente oppure inizializza il conteggio.",'''Map<String,Integer> counts=new HashMap<>();for(String word:List.of("a","b","a"))counts.merge(word,1,Integer::sum);System.out.println(counts.get("a"));''',"2", "map merge counter")
    add("Usare Deque come coda", "Espone operazioni FIFO con pollFirst e gestisce la terminazione su null.",'''Deque<String> queue=new ArrayDeque<>();queue.addLast("prima");queue.addLast("seconda");String value;while((value=queue.pollFirst())!=null)System.out.println(value);''',"prima e seconda; ArrayDeque non consente elementi null.","deque fifo queue")
    add("Estrarre il minimo con PriorityQueue", "Utilizza un heap con ordine naturale crescente.",'''PriorityQueue<Integer> queue=new PriorityQueue<>(List.of(9,2,5));while(!queue.isEmpty())System.out.println(queue.remove());''',"2,5,9; l'iteratore del contenitore non restituisce necessariamente l'ordine di priorità.","priorityqueue heap minimum")
    add("Definire un oggetto valore con record", "Ottiene accessori, equals e hashCode coerenti con i componenti.",'''Point first=new Point(2,3),second=new Point(2,3);System.out.println(first.equals(second));System.out.println(first.x());''',"true e 2; l'immutabilità dei componenti non è automaticamente profonda.","record equality value", "record Point(int x,int y){}")
    add("Limitare implementazioni con sealed", "Dichiara in modo esplicito i tipi permessi per una gerarchia.",'''Shape shape=new Square(4);System.out.println(shape.area());''',"16.0", "sealed permits hierarchy", "sealed interface Shape permits Square{double area();}\nrecord Square(double side)implements Shape{public double area(){return side*side;}}")
    add("Passare una implementazione di interfaccia", "Usa una lambda per fornire un comportamento con una sola operazione astratta.",'''Formatter formatter=value->String.format(Locale.ROOT,"%.2f",value);System.out.println(formatter.format(3));''',"3.00", "functionalinterface lambda strategy", "@FunctionalInterface interface Formatter{String format(double value);}")
    add("Preservare tipi con un metodo generico", "Restituisce il primo elemento mantenendo il tipo senza cast.",'''System.out.println(first(List.of("Ada","Luca")));''',"Ada; una lista vuota genera IllegalArgumentException.","generic method type parameter", "static <T>T first(List<T> values){if(values.isEmpty())throw new IllegalArgumentException(\"Lista vuota\");return values.get(0);}")
    add("Conservare la causa di un'eccezione", "Aggiunge contesto applicativo mantenendo l'errore originale.",'''try{try{Integer.parseInt("abc");}catch(NumberFormatException cause){throw new IllegalArgumentException("Dato utente non valido",cause);}}catch(IllegalArgumentException error){System.out.println(error.getMessage()+":"+error.getCause().getClass().getSimpleName());}''',"Dato utente non valido:NumberFormatException", "exception cause diagnostics")
    add("Rilasciare automaticamente con try-with-resources", "Chiude una risorsa AutoCloseable anche quando il blocco fallisce.",'''try(DemoResource resource=new DemoResource()){resource.work();}''',"lavoro e chiusura.","try resources autocloseable", "static class DemoResource implements AutoCloseable{void work(){System.out.println(\"lavoro\");}public void close(){System.out.println(\"chiusura\");}}")
    add("Leggere e scrivere UTF-8 con Files", "Usa un file temporaneo e ne assicura la rimozione nel finally.",'''Path path=Files.createTempFile("catalog-java-",".txt");try{Files.writeString(path,"Città",StandardCharsets.UTF_8);System.out.println(Files.readString(path,StandardCharsets.UTF_8));}finally{Files.deleteIfExists(path);}''',"Città e cleanup del file temporaneo.","files nio utf8 temporary")
    add("Comporre risultati con CompletableFuture", "Trasforma un risultato asincrono senza bloccare fra gli stadi.",'''CompletableFuture<Integer> future=CompletableFuture.supplyAsync(()->21).thenApply(value->value*2);System.out.println(future.join());''',"42; join propaga errori attraverso CompletionException.","completablefuture async compose")
    add("Terminare correttamente un ExecutorService", "Ferma l'accettazione di lavoro e attende i task in un blocco finally.",'''ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Integer> result=pool.submit(()->6*7);System.out.println(result.get());}finally{pool.shutdown();if(!pool.awaitTermination(5,TimeUnit.SECONDS))pool.shutdownNow();}''',"42 e chiusura del pool.","executorservice shutdown future")
    add("Verificare contratti senza dipendere da -ea", "Usa verifiche esplicite quando i test devono essere attivi in ogni configurazione JVM.",'''require(total(List.of(2,3))==5,"somma");require(total(List.of())==0,"vuoto");System.out.println("2 contratti verificati");''',"2 contratti verificati; assert Java richiederebbe -ea per essere eseguito.","testing assertion contract", "static int total(List<Integer> values){return values.stream().mapToInt(Integer::intValue).sum();}\nstatic void require(boolean condition,String message){if(!condition)throw new IllegalStateException(message);}")
    program(b,"Progetto completo catalogo libri Java", "Separa dominio, programma e test in tre classi Java17 con ricerca e gestione di identificativi univoci.",'''public class Main{public static void main(String[]args){Inventory inventory=new Inventory();inventory.add("ISBN-1","Programmare Java");System.out.println(inventory.find("ISBN-1").orElse("assente"));}}''',filename="Main.java",files={
      "Inventory.java":'''import java.util.*;
public final class Inventory{
private final Map<String,String> books=new LinkedHashMap<>();
public void add(String id,String title){if(id==null||id.isBlank()||title==null||title.isBlank())throw new IllegalArgumentException("ID e titolo richiesti");if(books.putIfAbsent(id,title)!=null)throw new IllegalArgumentException("ID duplicato");}
public Optional<String> find(String id){return Optional.ofNullable(books.get(id));}
public Map<String,String> snapshot(){return Map.copyOf(books);}
}''',
      "InventoryTest.java":'''public class InventoryTest{public static void main(String[]args){Inventory inventory=new Inventory();inventory.add("1","Java");if(!inventory.find("1").orElseThrow().equals("Java"))throw new IllegalStateException("ricerca");if(inventory.find("assente").isPresent())throw new IllegalStateException("assenza");try{inventory.add("1","Altro");throw new IllegalStateException("duplicato accettato");}catch(IllegalArgumentException expected){}System.out.println("3 contratti verificati");}}''',
      "README.md":"# Catalogo libri Java\n\nRichiede JDK17+, nessun Maven né pacchetto esterno. `javac -encoding UTF-8 --release 17 Main.java Inventory.java InventoryTest.java`, `java InventoryTest`, `java Main`. I dati sono in memoria e non vengono conservati tra gli avvii. L'ID è un codice sintetico: non valida la struttura degli ISBN reali. snapshot restituisce una copia non modificabile; i titoli sono String immutabili.\n"},command="javac -encoding UTF-8 --release 17 Main.java Inventory.java InventoryTest.java\njava InventoryTest\njava Main",expected="Test:3 contratti verificati. Programma:Programmare Java.",tags=("project","class","optional","map","testing"),project=True,section="Progetti completi")
